import json
import tempfile
import unittest
from pathlib import Path

from update_stars import FetchError, fetch_lists, fetch_stars, render, to_json, update

HEADER = (
    '<!--lint disable awesome-contributing awesome-license awesome-list-item match-punctuation '
    'no-repeat-punctuation no-undefined-references awesome-spell-check-->\n'
    '# Awesome Stars [![Awesome](https://awesome.re/badge.svg)](https://github.com/sindresorhus/awesome)\n'
    '\n'
    '> A curated list of my GitHub stars! Generated by [starred](https://github.com/maguowei/starred).\n'
    '\n'
    '## Contents\n'
    '\n'
)

FOOTER = (
    '\n'
    '## License\n'
    '\n'
    '[![CC0](http://mirrors.creativecommons.org/presskit/buttons/88x31/svg/cc-zero.svg)]'
    '(https://creativecommons.org/publicdomain/zero/1.0/)\n'
    '\n'
    'To the extent possible under law, [me](https://github.com/me) '
    'has waived all copyright and related or neighboring rights to this work.\n'
    '\n'
)


STARRED_AT = '2026-11-01T00:00:00Z'


def node(name, language=None, topics=(), description='Desc', private=False, **fields):
    return {
        'nameWithOwner': name,
        'url': f'https://github.com/{name}',
        'description': description,
        'isPrivate': private,
        'languages': {'edges': [{'node': {'name': language}}] if language else []},
        'repositoryTopics': {
            'nodes': [{'topic': {'name': t, 'stargazerCount': stars}} for t, stars in topics]
        },
        'homepageUrl': None,
        'stargazerCount': 0,
        'forkCount': 0,
        'isArchived': False,
        'isFork': False,
        'licenseInfo': None,
        'createdAt': 'C',
        'pushedAt': 'P',
        'starredAt': STARRED_AT,
        **fields,
    }


class RenderByLanguage(unittest.TestCase):
    def test_groups_by_language_sorted_keeping_star_order(self):
        nodes = [
            node('a/py2', 'Python'),
            node('a/c', 'C#'),
            node('a/py1', 'Python', description=None),
            node('a/none'),
        ]

        expected = HEADER + (
            '- [C#](#c#)\n'
            '- [Others](#others)\n'
            '- [Python](#python)\n'
            '\n'
            '## C# # \n'
            '\n'
            '- [a/c](https://github.com/a/c) - Desc\n'
            '\n'
            '## Others \n'
            '\n'
            '- [a/none](https://github.com/a/none) - Desc\n'
            '\n'
            '## Python \n'
            '\n'
            '- [a/py2](https://github.com/a/py2) - Desc\n'
            '- [a/py1](https://github.com/a/py1) - \n'
            '\n'
        ) + FOOTER

        self.assertEqual(render(nodes, 'me').decode(), expected)


class RenderRules(unittest.TestCase):
    def test_by_topic_keeps_popular_topics_and_falls_back_to_others(self):
        nodes = [
            node('a/both', 'Go', topics=[('cli', 501), ('rare', 500)]),
            node('a/multi', topics=[('cli', 900), ('web', 900)]),
            node('a/unpopular', topics=[('rare', 3)]),
        ]

        expected = HEADER + (
            '- [cli](#cli)\n'
            '- [others](#others)\n'
            '- [web](#web)\n'
            '\n'
            '## cli \n'
            '\n'
            '- [a/both](https://github.com/a/both) - Desc\n'
            '- [a/multi](https://github.com/a/multi) - Desc\n'
            '\n'
            '## others \n'
            '\n'
            '- [a/unpopular](https://github.com/a/unpopular) - Desc\n'
            '\n'
            '## web \n'
            '\n'
            '- [a/multi](https://github.com/a/multi) - Desc\n'
            '\n'
        ) + FOOTER

        self.assertEqual(render(nodes, 'me', by_topic=True).decode(), expected)

    def test_skips_private_repositories(self):
        output = render([node('a/secret', 'Go', private=True), node('a/open', 'Go')], 'me')

        self.assertNotIn(b'a/secret', output)
        self.assertIn(b'a/open', output)

    def test_sanitizes_descriptions(self):
        description = '  <b>\nx' + 'y' * 300
        output = render([node('a/r', 'Go', description=description)], 'me').decode()

        # Escaping and newline removal happen before stripping and truncating to 200 chars.
        expected = '&lt;b&gt;x' + 'y' * 190
        self.assertIn(f'- [a/r](https://github.com/a/r) - {expected}\n', output)


